const menu = document.querySelector('.menu');
const nav = document.querySelector('nav');
menu.addEventListener('click', () => { const open = nav.classList.toggle('open'); menu.setAttribute('aria-expanded', String(open)); menu.setAttribute('aria-label', open ? 'Zatvori meni' : 'Otvori meni'); });
nav.querySelectorAll('a').forEach(link => link.addEventListener('click', () => { nav.classList.remove('open'); menu.setAttribute('aria-expanded', 'false'); menu.setAttribute('aria-label', 'Otvori meni'); nav.querySelectorAll('a').forEach(a => a.classList.remove('active')); link.classList.add('active'); }));
document.getElementById('year').textContent = new Date().getFullYear();
const dialog = document.getElementById('program-dialog');
const descriptions = { 'Start Strong': 'Predlog početnog programa sa fokusom na osnovne pokrete, pravilno izvođenje i stvaranje redovne rutine.', 'Strong Body': 'Predlog programa za razvoj snage celog tela, namenjen osobama koje već poznaju osnovne vežbe.', 'Online Coaching': 'Predlog individualne online saradnje, sa planom prema tvojoj opremi, rasporedu i iskustvu.' };
document.querySelectorAll('.program').forEach(button => button.addEventListener('click', () => { const name = button.dataset.program; document.getElementById('dialog-title').textContent = name; document.getElementById('dialog-copy').textContent = descriptions[name]; document.querySelector('select[name="program"]').value = name; dialog.showModal(); }));
document.querySelector('.close').addEventListener('click', () => dialog.close());
document.getElementById('choose-program').addEventListener('click', () => dialog.close());
dialog.addEventListener('click', event => { if (event.target === dialog) { const r = dialog.getBoundingClientRect(); if (event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom) dialog.close(); } });
document.getElementById('contact-form').addEventListener('submit', event => { event.preventDefault(); const data = new FormData(event.target); const text = `Upit za trening — Tijana\n\nIme: ${data.get('ime')}\nE-mail: ${data.get('email')}\nProgram: ${data.get('program')}\n\nCilj:\n${data.get('poruka')}\n\nOvaj upit nije poslat. Prosledite ga kada zvanični kontakt bude dostupan.`; const url = URL.createObjectURL(new Blob([text], { type: 'text/plain;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = 'tijana-upit.txt'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); document.getElementById('form-status').textContent = 'Upit je pripremljen za preuzimanje. Podaci nisu poslati.'; });
